// IMPERATIVE - You tell HOW step by step (Old way)
// You manually find element and update it
const button = document.querySelector('#likeBtn');
const countSpan = document.querySelector('#count');
let likes = 5;
button.addEventListener('click', () => {
 likes++;
 countSpan.innerText = likes; // You manually update UI
});

// DECLARATIVE - You tell WHAT you want (React way)
function LikeButton() {
 const [likes, setLikes] = React.useState(5);
 return <button onClick={() => setLikes(likes + 1)}>Likes: {likes}</button>;
 // You just say WHAT UI should be for given likes. React updates it!
}

