// Task: Show list of 3 lessons - how would you do it?
// jQuery way: Manually create <li> elements with document.createElement - 10 lines
// React way: Just map over data - 3 lines and clean!

function LessonsList() {
 const lessons = ["Introduction", "JSX & Components", "Props"];
 return (
 <ul>
 {lessons.map((lesson, index) => (
 <li key={index}>{lesson}</li>
 ))}
 </ul>
 );
}

// MODERN WAY - Functional + Hooks - USE THIS
function Welcome() {
 const [name] = React.useState("Prince");
 return <h1>Hello {name}</h1>;
}

// OLD WAY - Class Component - DON'T USE, just recognize it
class WelcomeOld extends React.Component {
 render() {
 return <h1>Hello {this.state.name}</h1>;
 }
}
