// File: src/App.jsx - This is the standard every pro uses
import { useState } from 'react';

// Component 1: Header
function Header() {
 return (
 <header>
 <h1>Code Academy</h1>
 <p>Learn • Build • Master React</p>
 </header>
 );
}

// Component 2: About React (What you learned today)
function AboutReact() {
 return (
 <div>
 <h2>What is React?</h2>
 <ul>
 <li>Created by Jordan Walke at Facebook in 2011 (FaxJS)</li>
 <li>Open sourced in 2013</li>
 <li>Library for building UIs with components</li>
 <li>Uses Virtual DOM for speed</li>
 <li>Declarative: Tell WHAT, not HOW</li>
 </ul>
 </div>
 );
}

// Component 3: Counter to show React is interactive
function Counter() {
 const [count, setCount] = useState(0);
 return (
 <div>
 <h2>Interactive Demo - React State</h2>
 <p>You clicked {count} times - React updates ONLY this number, not whole page!</p>
 <button onClick={() => setCount(count + 1)}>Click Me</button>
 </div>
 );
}

// Main App - Combines all
function App() {
 return (
 <div>
 <Header />
 <AboutReact />
 <Counter />
 <footer>
 <p>Built with React Standard Structure | Lesson 1 Complete</p>
 </footer>
 </div>
 );
}

export default App;

